<dialog data-workspace-drawer aria-labelledby="workspace-drawer-title" class="fixed inset-y-0 left-auto right-0 m-0 h-dvh max-h-none w-full max-w-[640px] border-0 bg-white p-0 text-slate-900 shadow-2xl backdrop:bg-slate-950/50 dark:bg-slate-900 dark:text-slate-100">
    <div class="flex h-full min-h-0 flex-col">
        <header class="flex shrink-0 items-center justify-between gap-3 border-b border-slate-200 px-5 py-4 dark:border-slate-700"><h2 id="workspace-drawer-title" class="text-lg font-semibold">Revisar información</h2><button type="button" data-workspace-close aria-label="Cerrar panel" class="rounded-xl p-2 hover:bg-slate-100 dark:hover:bg-slate-800"><x-ui.icon name="x" class="h-5 w-5" /></button></header>
        <div data-workspace-content class="min-h-0 flex-1 overflow-y-auto overscroll-contain p-4 sm:p-5"></div>
        <div data-workspace-discard hidden role="alertdialog" aria-modal="true" aria-labelledby="discard-workspace-title" aria-describedby="discard-workspace-description" class="absolute inset-0 z-10 bg-white/95 p-6 dark:bg-slate-900/95"><div class="mx-auto mt-20 max-w-sm rounded-2xl border border-slate-200 bg-white p-5 shadow-xl dark:border-slate-700 dark:bg-slate-900"><h3 id="discard-workspace-title" class="font-semibold">Tienes cambios sin guardar</h3><p id="discard-workspace-description" class="mt-2 text-sm text-slate-500">Si cierras el panel, perderás los cambios de este formulario.</p><div class="mt-5 flex flex-wrap gap-3"><button type="button" data-workspace-keep class="rounded-xl bg-brand-600 px-4 py-2 text-sm font-semibold text-white">Seguir editando</button><button type="button" data-workspace-abandon class="rounded-xl border border-slate-300 px-4 py-2 text-sm font-semibold dark:border-slate-600">Descartar cambios</button></div></div></div>
    </div>
</dialog>
